import { useId, useRef, type CSSProperties, type ReactNode } from 'react';
import './ApplicationShell.css';
type Section = { id: string; label: string; links: { id: string; label: string; href: string }[] };
type Props = { toolbar: ReactNode; sections: Section[]; activeId: string; workspace: ReactNode; inspector: ReactNode; inspectorWidth: number; onInspectorWidthChange: (width: number) => void };
export function ApplicationShell({ toolbar, sections, activeId, workspace, inspector, inspectorWidth, onInspectorWidthChange }: Props) {
 const id = useId();
 const drag = useRef<{ x: number; width: number } | null>(null);
 const width = Math.max(240, Math.min(480, inspectorWidth));
 const resize = (value: number) => onInspectorWidthChange(Math.max(240, Math.min(480, value)));
 return <div className="application-shell" style={{ '--inspector-width': width + 'px' } as CSSProperties}>
 <a className="skip-link" href={'#' + id + '-workspace'}>Skip to workspace</a>
 <header className="shell-toolbar" aria-label="Application toolbar">{toolbar}</header>
 <div className="shell-panes">
 <nav className="shell-navigation shell-scroll" aria-label="Main navigation" tabIndex={0}>{sections.map(section => <section key={section.id} aria-labelledby={id + section.id}><h2 id={id + section.id}>{section.label}</h2><ul>{section.links.map(link => <li key={link.id}><a href={link.href} aria-current={activeId === link.id ? 'page' : undefined}>{link.label}</a></li>)}</ul></section>)}</nav>
 <main id={id + '-workspace'} className="shell-workspace shell-scroll" tabIndex={0} aria-label="Workspace">{workspace}</main>
 <div className="shell-resizer" role="separator" tabIndex={0} aria-label="Inspector width" aria-orientation="vertical" aria-controls={id + '-inspector'} aria-valuemin={240} aria-valuemax={480} aria-valuenow={width} aria-valuetext={width + ' pixels'}
 onKeyDown={event => { const next = event.key === 'ArrowLeft' ? width + 16 : event.key === 'ArrowRight' ? width - 16 : event.key === 'Home' ? 240 : event.key === 'End' ? 480 : null; if (next !== null) { event.preventDefault(); resize(next); } }}
 onPointerDown={event => { if (event.button !== 0) return; drag.current = { x: event.clientX, width }; event.currentTarget.setPointerCapture(event.pointerId); event.currentTarget.focus(); }}
 onPointerMove={event => { if (drag.current) resize(drag.current.width + drag.current.x - event.clientX); }}
 onPointerUp={event => { drag.current = null; event.currentTarget.releasePointerCapture(event.pointerId); }}
 onPointerCancel={() => { drag.current = null; }} onLostPointerCapture={() => { drag.current = null; }} />
 <aside id={id + '-inspector'} className="shell-inspector shell-scroll" aria-label="Inspector" tabIndex={0}>{inspector}</aside>
 </div></div>;
}
// The application supplies product selection, pane content, width state, and persistence.
// This layout component performs no storage writes or domain-state management.

