.application-shell{height:100dvh;display:grid;grid-template-rows:auto minmax(0,1fr);overflow:hidden;background:#fff;color:#182030}
.shell-toolbar{padding:10px 16px;border-bottom:1px solid #bdc3cc;display:flex;align-items:center;flex-wrap:wrap;gap:10px;max-height:35dvh;overflow:auto}
.shell-panes{display:grid;grid-template-columns:220px minmax(0,1fr) 8px var(--inspector-width);min-height:0;min-width:0;overflow:hidden}
.shell-scroll{min-height:0;min-width:0;overflow:auto;overscroll-behavior:contain;padding:16px;overflow-wrap:anywhere}
.shell-navigation{border-right:1px solid #bdc3cc}
.shell-navigation ul{list-style:none;margin:0;padding:0}
.shell-navigation h2{font-size:.8rem;margin-block:16px 8px}
.shell-navigation a{display:block;padding:8px;border-radius:5px;color:inherit}
.shell-navigation a[aria-current=page]{background:#e1eaff;font-weight:700}
.shell-inspector{border-left:1px solid #bdc3cc}
.shell-resizer{cursor:col-resize;touch-action:none;background:#e4e7ed}
.application-shell :focus-visible{outline:2px solid #255ec9;outline-offset:-2px}
.skip-link{position:absolute;left:8px;top:8px;transform:translateY(-200%);z-index:2;background:white;padding:8px}
.skip-link:focus{transform:none}
@media(max-width:900px){.shell-panes{grid-template-columns:160px minmax(0,1fr) 8px min(var(--inspector-width),35vw)}}
@media(max-width:640px){.shell-panes{display:block;overflow:auto;overscroll-behavior:contain}.shell-scroll{overflow:visible;min-height:auto}.shell-navigation{border-right:0;border-bottom:1px solid #bdc3cc}.shell-inspector{border-left:0;border-top:1px solid #bdc3cc}.shell-resizer{display:none}.shell-workspace{min-height:40dvh}}
